import { getTimeScale, scaleDuration } from "../platform/compat/time-scale.js";
/** Return the current test time scale. Preserved for compatibility. */
export function getTestTimeScale() {
    return getTimeScale();
}
/** Scale a duration for the current test runtime. */
export function scaleMs(ms, minMs = 1) {
    return scaleDuration(ms, minMs);
}
// no cleanup needed: one-shot
/** Wait for a test-scaled duration. */
export function testDelay(ms) {
    return new Promise((resolve) => setTimeout(resolve, scaleMs(ms)));
}
